import pyomo.environ as pyo

DATA = {
    "campaign_budget": 2501.0,  # renamed safely as budget_map key alias below
}

# --- Core numeric constants lifted verbatim from problem text ---
DATA = {
    "pop": {
        0: 2882, 1: 4926, 2: 3930, 3: 3468, 4: 3415,
        5: 2697, 6: 2746, 7: 3817, 8: 4806, 9: 2889,
        10: 2276, 11: 2087, 12: 4452, 13: 3015, 14: 2305,
        15: 3196, 16: 4854, 17: 4466, 18: 2154, 19: 4661,
        20: 2587, 21: 4013, 22: 3519, 23: 4837, 24: 2465,
        25: 3807, 26: 4498, 27: 3423, 28: 2832, 29: 3064,
    },
    "cost": {
        0: 453, 1: 208, 2: 223, 3: 336, 4: 473,
        5: 274, 6: 257, 7: 436, 8: 440, 9: 242,
        10: 272, 11: 277, 12: 232, 13: 292, 14: 369,
        15: 318, 16: 475, 17: 238, 18: 440, 19: 496,
        20: 275, 21: 240, 22: 291, 23: 320, 24: 462,
    },
    "budget": 2501.0,
    # coverage lists: explicit where given; default to all towers otherwise
    "covers": {
        0: [3, 4, 6, 7, 8, 9, 10, 11, 13, 14, 15, 18, 20],
        1: [0, 1, 3, 4, 5, 8, 11, 13, 15, 16, 20, 23, 24],
    },
}

# Build full coverage mapping: default = all towers except where listed
ALL_TOWERS = tuple(DATA["cost"].keys())
ALL_AREAS = tuple(DATA["pop"].keys())
data_default_covers = {j: list(DATA["covers"].get(j, ALL_TOWERS)) for j in ALL_AREAS}


def build_model(data=None):
    d = data or DATA
    covers_dict = d.get("covers", data_default_covers)

    m = pyo.ConcreteModel()

    m.I = pyo.Set(initialize=list(d["cost"].keys()), ordered=True)
    m.J = pyo.Set(initialize=list(d["pop"].keys()), ordered=True)

    # Build the coverage matrix as a set per area
    def cov_init(m, j):
        vals = covers_dict.get(j, list(d["cost"].keys()))
        return [i for i in vals if i in d["cost"]]
    m.Cover = pyo.Set(m.J, initialize=cov_init, ordered=True)

    m.build = pyo.Var(m.I, within=pyo.Binary)
    m.covered = pyo.Var(m.J, within=pyo.Binary)

    # Objective: maximize total covered population
    def obj_rule(m):
        return sum(d["pop"][j] * m.covered[j] for j in m.J)
    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Coverage implication: covered[j] <= sum_{i covers j} build[i]
    def cover_rule(m, j):
        return m.covered[j] <= sum(m.build[i] for i in m.Cover[j])
    m.coverage_link = pyo.Constraint(m.J, rule=cover_rule)

    # Budget: total build cost <= budget
    def budget_rule(m):
        return sum(d["cost"][i] * m.build[i] for i in m.I) <= d["budget"]
    m.budget_con = pyo.Constraint(rule=budget_rule)

    return m


